//go:build darwin || linux

package app

import (
	"context"
	"database/sql"
	"encoding/json"
	"fmt"
	"io"
	"log"
	"net/http"
	"net/http/httptest"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/teamva-ai/teamva/server/internal/domain"
)

// This is an adversarial synthetic Responses server, NOT an external model.
// The actual Codex app-server must execute exec_command, author its Run's IPC,
// and read the response generated by the real FileBridge/ToolBroker/ToolService.
// Neither this fixture nor the native shell writes a response or a business DB.
//
// ToolService intentionally rejects self-mentions BEFORE WriteRunIssueComment.
// Thus the same self-mention cannot also hit SQLite's defense-in-depth branch.
// The duplicate-target probe below reaches that real SQLite validator through
// precisely the same native/IPC path, and the final summary commits normally.
func TestNativeCodexSelfMentionContinuationWithoutExternalModel(t *testing.T) {
	if os.Getenv("TEAMVA_NATIVE_SELF_MENTION_TEST") != "1" {
		t.Skip("opt in to isolated real Codex + synthetic localhost model fixture")
	}
	binary := os.Getenv("TEAMVA_CODEX_BINARY")
	if binary == "" {
		var err error
		binary, err = exec.LookPath("codex")
		if err != nil {
			t.Fatal("native Codex executable missing")
		}
	}
	binary, _ = filepath.Abs(binary)
	python, err := exec.LookPath("python3")
	if err != nil {
		t.Fatal(err)
	}
	root := t.TempDir()
	if parent := os.Getenv("TEAMVA_SELF_MENTION_EVIDENCE_ROOT"); parent != "" {
		root, err = os.MkdirTemp(parent, "self-mention-continuation-native-")
		if err != nil {
			t.Fatal(err)
		}
	}
	root, _ = filepath.EvalSymlinks(root)
	t.Logf("isolated evidence: %s", root)
	mkdir := func(name string) string {
		t.Helper()
		path := filepath.Join(root, name)
		if err := os.MkdirAll(path, 0700); err != nil {
			t.Fatal(err)
		}
		return path
	}
	home, data := mkdir("home"), mkdir("data")
	// Set these before NewLocal/factory LinkAuth, not just in the CLI wrapper.
	for key, value := range map[string]string{
		"HOME": home, "CODEX_HOME": mkdir("home/.codex"),
		"XDG_CONFIG_HOME": mkdir("home/config"), "XDG_DATA_HOME": mkdir("home/share"),
		"XDG_CACHE_HOME": mkdir("home/cache"),
	} {
		t.Setenv(key, value)
	}
	quote := func(s string) string { return "'" + strings.ReplaceAll(s, "'", "'\\''") + "'" }
	writeJSON := func(name string, value any) {
		t.Helper()
		body, err := json.MarshalIndent(value, "", "  ")
		if err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(filepath.Join(root, name), append(body, '\n'), 0600); err != nil {
			t.Fatal(err)
		}
	}
	db, err := sql.Open("sqlite", "file:"+filepath.Join(data, "app.db")+"?mode=ro&_pragma=busy_timeout(5000)")
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	type counts struct {
		Comments, Mentions, Instances, Runs, Receipts int
	}
	snapshot := func(issueID string) (counts, error) {
		var c counts
		queries := []struct {
			query string
			dest  *int
		}{
			{"SELECT count(*) FROM issue_comments WHERE issue_id=? AND deleted_at IS NULL", &c.Comments},
			{"SELECT count(*) FROM issue_comment_mentions m JOIN issue_comments c ON c.id=m.comment_id WHERE c.issue_id=?", &c.Mentions},
			{"SELECT count(*) FROM issue_agent_instances WHERE issue_id=? AND deleted_at IS NULL", &c.Instances},
			{"SELECT count(*) FROM runs WHERE issue_id=? AND deleted_at IS NULL", &c.Runs},
			{"SELECT count(*) FROM issue_tool_comment_requests q JOIN runs r ON r.id=q.run_id WHERE r.issue_id=?", &c.Receipts},
		}
		for _, q := range queries {
			if err := db.QueryRow(q.query, issueID).Scan(q.dest); err != nil {
				return c, err
			}
		}
		return c, nil
	}
	var mu sync.Mutex
	var issueID, selfID, otherID string
	var stage int
	var gatewayErr error
	var observations []map[string]any
	var ipcRoot string
	bridgeRE := regexp.MustCompile(`\.teamva/tool-requests/(run_[A-Za-z0-9_-]+)`)
	// Retry the exact same self request (same IPC filename, payload and stable
	// idempotency key) after closure. Removing only its response forces a fresh
	// FileBridge delivery, rather than merely rereading an old rejection.
	steps := []string{"self-before-close", "self-after-close", "closed-delegation", "duplicate-target", "summary"}
	var closeIssue func() error
	var reopenIssue func() error
	gateway := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		body, readErr := io.ReadAll(io.LimitReader(r.Body, 8<<20))
		mu.Lock()
		defer mu.Unlock()
		fail := func(err error) {
			gatewayErr = err
			http.Error(w, "local fixture assertion failed", 500)
		}
		if readErr != nil || r.Method != "POST" || r.URL.Path != "/v1/responses" {
			fail(fmt.Errorf("unexpected fixture request: %s %s read=%v", r.Method, r.URL.Path, readErr))
			return
		}
		if stage > len(steps) {
			fail(fmt.Errorf("unexpected extra model request"))
			return
		}
		if stage == 0 {
			match := bridgeRE.FindSubmatch(body)
			if len(match) != 2 || selfID == "" || issueID == "" {
				fail(fmt.Errorf("native request missing real Run IPC or identity"))
				return
			}
			ipcRoot = ".teamva/tool-requests/" + string(match[1])
		}
		var previous map[string]any
		if stage > 0 {
			var request struct {
				Input []struct {
					Type   string          `json:"type"`
					Output json.RawMessage `json:"output"`
				} `json:"input"`
			}
			if err := json.Unmarshal(body, &request); err != nil {
				fail(err)
				return
			}
			var nativeOutput string
			for _, input := range request.Input {
				if input.Type == "function_call_output" {
					_ = json.Unmarshal(input.Output, &nativeOutput)
				}
			}
			// Only accept actual JSON printed by the native command after reading
			// host-owned *.response.json. Never infer rejection from model prose.
			at := strings.LastIndex(nativeOutput, "HOST_RESPONSE=")
			if at < 0 || json.Unmarshal([]byte(strings.TrimSpace(nativeOutput[at+len("HOST_RESPONSE="):])), &previous) != nil {
				fail(fmt.Errorf("native tool did not return host response at stage %d: %s", stage, nativeOutput))
				return
			}
			message, _ := previous["message"].(string)
			want := []string{"不能直接 @ 自己", "不能直接 @ 自己", "任务已结束", "不能重复 @ 同一个 Agent", ""}[stage-1]
			if (stage < len(steps) && (previous["ok"] != false || !strings.Contains(message, want))) || (stage == len(steps) && previous["ok"] != true) {
				fail(fmt.Errorf("wrong real host outcome at stage %d: %+v", stage, previous))
				return
			}
		}
		c, err := snapshot(issueID)
		if err != nil {
			fail(err)
			return
		}
		wantCounts := counts{Instances: 1, Runs: 1}
		if stage == len(steps) {
			wantCounts.Comments, wantCounts.Receipts = 1, 1
		}
		if c != wantCounts {
			fail(fmt.Errorf("side effects at stage %d: %+v want %+v", stage, c, wantCounts))
			return
		}
		completedStep := "before-native-tools"
		if stage > 0 {
			completedStep = steps[stage-1]
		}
		observations = append(observations, map[string]any{"stage": stage, "completed_step": completedStep, "host_response": previous, "sqlite_counts": c, "path": r.URL.Path})
		if stage == 1 {
			if err := closeIssue(); err != nil {
				fail(err)
				return
			}
		}
		if stage == 3 {
			if err := reopenIssue(); err != nil {
				fail(err)
				return
			}
		}
		var item map[string]any
		if stage < len(steps) {
			mentions := []string{}
			text := "deterministic public summary after rejected self mention"
			switch stage {
			case 0, 1:
				mentions, text = []string{selfID}, "must never publish self delegation"
			case 2:
				mentions, text = []string{otherID}, "must never publish closed delegation"
			case 3:
				mentions, text = []string{otherID, otherID}, "must never publish duplicate delegation"
			}
			payload, _ := json.Marshal(map[string]any{"body": text, "mentioned_agent_ids": mentions})
			filename := steps[stage]
			if stage < 2 {
				filename = "same-self-request"
			}
			path := ipcRoot + "/issue_comment_create/req-" + filename + ".json"
			program := "import pathlib,time\np=pathlib.Path(" + fmt.Sprintf("%q", path) + ")\nr=pathlib.Path(str(p)+'.response.json')\nr.unlink(missing_ok=True)\np.write_text(" + fmt.Sprintf("%q", string(payload)) + ")\nfor _ in range(250):\n if r.exists():\n  print('HOST_RESPONSE='+r.read_text().strip());break\n time.sleep(.1)\nelse: raise RuntimeError('host response timeout')\n"
			args, _ := json.Marshal(map[string]any{"cmd": quote(python) + " -c " + quote(program), "max_output_tokens": 2000, "yield_time_ms": 10000})
			item = map[string]any{"type": "function_call", "name": "exec_command", "call_id": "native-" + steps[stage], "arguments": string(args)}
		} else {
			item = map[string]any{"type": "message", "id": "fixture-final", "role": "assistant", "content": []any{map[string]any{"type": "output_text", "text": "LOCAL_SYNTHETIC_FIXTURE_DONE"}}}
		}
		stage++
		w.Header().Set("Content-Type", "text/event-stream")
		for _, event := range []map[string]any{
			{"type": "response.created", "response": map[string]any{"id": fmt.Sprintf("local-%d", stage)}},
			{"type": "response.output_item.done", "output_index": 0, "item": item},
			{"type": "response.completed", "response": map[string]any{"id": fmt.Sprintf("local-%d", stage), "status": "completed", "output": []any{item}, "usage": map[string]any{"input_tokens": 1, "output_tokens": 1, "total_tokens": 2}}},
		} {
			encoded, _ := json.Marshal(event)
			fmt.Fprintf(w, "event: %s\ndata: %s\n\n", event["type"], encoded)
		}
	}))
	defer gateway.Close()
	wrapper := filepath.Join(root, "isolated-native-codex")
	// A clean allow-list: no account/config, API key, proxy or external endpoint
	// is inherited. Global CLI config overrides keep the host system prompt and
	// actual native permission profile unchanged.
	script := "#!/bin/sh\nexec /usr/bin/env -i HOME=" + quote(home) + " CODEX_HOME=\"${CODEX_HOME:-" + filepath.Join(home, ".codex") + "}\" PATH=" + quote(os.Getenv("PATH")) +
		" XDG_CONFIG_HOME=" + quote(filepath.Join(home, "config")) + " XDG_DATA_HOME=" + quote(filepath.Join(home, "share")) + " XDG_CACHE_HOME=" + quote(filepath.Join(home, "cache")) + " " + quote(binary) +
		" -c 'model_provider=\"fixture\"' -c 'model=\"gpt-6.1-sol\"' -c 'cli_auth_credentials_store=\"ephemeral\"' -c 'features.unified_exec=true' -c 'features.plugins=false' -c 'features.apps=false'" +
		" -c 'model_providers.fixture.name=\"offline synthetic fixture\"' -c 'model_providers.fixture.wire_api=\"responses\"' -c 'model_providers.fixture.requires_openai_auth=false' -c " + quote("model_providers.fixture.base_url=\""+gateway.URL+"/v1\"") + " \"$@\"\n"
	if err := os.WriteFile(wrapper, []byte(script), 0700); err != nil {
		t.Fatal(err)
	}
	logs, err := os.OpenFile(filepath.Join(root, "service.log"), os.O_CREATE|os.O_WRONLY, 0600)
	if err != nil {
		t.Fatal(err)
	}
	defer logs.Close()
	ctx, cancel := context.WithTimeout(t.Context(), 90*time.Second)
	defer cancel()
	local, err := StartLocal(ctx, LocalConfig{Address: "127.0.0.1:0", DataDir: data, Version: "native-self-mention-fixture",
		ProviderPaths: map[string]string{"codex": wrapper, "opencode": "/usr/bin/false"}, Logger: log.New(logs, "", log.LstdFlags)})
	if err != nil {
		t.Fatal(err)
	}
	defer func() {
		closeCtx, closeCancel := context.WithTimeout(context.Background(), 15*time.Second)
		defer closeCancel()
		if err := local.Close(closeCtx); err != nil {
			t.Error(err)
		}
	}()
	// Real native discovery against the offline configuration, no fake auth.
	if err := local.dispatcher.Probe(ctx); err != nil {
		t.Fatal(err)
	}
	user, computer, err := local.repository.LocalIdentity()
	if err != nil {
		t.Fatal(err)
	}
	services, err := local.repository.ListAgentServices(ctx, user.ID, computer.ID)
	if err != nil {
		t.Fatal(err)
	}
	var serviceID string
	for _, service := range services {
		if service.Provider == "codex" && service.Status == "ready" && service.LoginStatus == "authenticated" {
			serviceID = service.ID
		}
	}
	if serviceID == "" {
		t.Fatalf("real offline Codex discovery not ready: %+v", services)
	}
	agent := func(name string) domain.Agent {
		t.Helper()
		a, err := local.repository.CreateConfiguredAgent(ctx, user.ID, domain.Agent{ComputerID: computer.ID, AgentServiceID: serviceID, Name: name, Model: "gpt-6.1-sol", Status: domain.AgentActive}, "Never directly mention yourself. Publish a final public summary using the host tool.", nil)
		if err != nil {
			t.Fatal(err)
		}
		return a
	}
	a, b := agent("native fixture A"), agent("native fixture B")
	project, err := local.repository.CreateProject(ctx, user.ID, domain.Project{ComputerID: computer.ID, Name: "isolated native self mention"})
	if err != nil {
		t.Fatal(err)
	}
	issue, err := local.repository.CreateIssue(ctx, user.ID, domain.Issue{ProjectID: project.ID, Title: "native adversarial self mention"})
	if err != nil {
		t.Fatal(err)
	}
	instance, _, err := local.repository.EnsureIssueAgentInstance(ctx, user.ID, issue.ID, a.ID)
	if err != nil {
		t.Fatal(err)
	}
	mu.Lock()
	issueID, selfID, otherID = issue.ID, a.ID, b.ID
	changeIssue := func(status string) error {
		current, err := local.repository.GetIssue(ctx, user.ID, issue.ID)
		if err != nil {
			return err
		}
		_, err = local.repository.UpdateIssue(ctx, user.ID, issue.ID, current.Version, func(v *domain.Issue) { v.Status = status })
		return err
	}
	closeIssue = func() error { return changeIssue(domain.IssueClosed) }
	reopenIssue = func() error { return changeIssue(domain.IssueOpen) }
	mu.Unlock()
	client := newTestClient(t)
	origin := local.Endpoint().Origin
	session := mutateJSON[testBootstrap](t, client, origin, http.MethodPost, "/v1/auth/local-session", "", map[string]any{})
	run := mutateJSONWithHeaders[domain.Run](t, client, origin, http.MethodPost, "/v1/issues/"+issue.ID+"/runs", session.CSRFToken,
		map[string]string{"Idempotency-Key": "native-self-mention-run"}, map[string]any{"issue_agent_instance_id": instance.ID, "input": "Run the isolated offline adversarial QA scenario.", "expected_issue_version": issue.Version})
	for {
		current, err := local.repository.GetRun(ctx, user.ID, run.ID)
		if err != nil {
			t.Fatal(err)
		}
		mu.Lock()
		err = gatewayErr
		mu.Unlock()
		if err != nil {
			t.Fatal(err)
		}
		if domain.IsRunTerminal(current.Status) {
			writeJSON("run.json", current)
			if current.Status != domain.RunSucceeded {
				t.Fatalf("native Run failed: %+v", current)
			}
			break
		}
		select {
		case <-ctx.Done():
			t.Fatal(ctx.Err())
		case <-time.After(100 * time.Millisecond):
		}
	}
	mu.Lock()
	observedStage := stage
	observed := append([]map[string]any(nil), observations...)
	mu.Unlock()
	writeJSON("gateway-observations.json", observed)
	if observedStage != len(steps)+1 {
		t.Fatalf("native fixture stopped early: requests=%d", observedStage)
	}
	comments, err := local.repository.ListIssueComments(ctx, user.ID, issue.ID)
	if err != nil || len(comments) != 1 || comments[0].AuthorAgentID != a.ID || comments[0].RunID != run.ID || comments[0].Status != domain.IssueCommentPublished || comments[0].Version != 1 || comments[0].Body != "deterministic public summary after rejected self mention" {
		t.Fatalf("final public summary mismatch: %+v err=%v", comments, err)
	}
	writeJSON("public-comments.json", comments)
	c, err := snapshot(issue.ID)
	if err != nil || c != (counts{Comments: 1, Instances: 1, Runs: 1, Receipts: 1}) {
		t.Fatalf("unexpected activation after terminal Run: %+v err=%v", c, err)
	}
	// Auth source is an empty synthetic home. Native CODEX_HOMEs must have no
	// auth.json links/files; discovery is authenticated only because the local
	// provider explicitly requires no account, not through fabricated login.
	if err := filepath.WalkDir(root, func(path string, d os.DirEntry, err error) error {
		if err == nil && d.Name() == "auth.json" {
			return fmt.Errorf("unexpected auth file in isolated fixture")
		}
		return err
	}); err != nil {
		t.Fatal(err)
	}
	writeJSON("summary.json", map[string]any{"result": "PASS", "real_cli": binary, "external_model_calls": 0, "synthetic_model_requests": observedStage, "data_dir": data, "run_id": run.ID, "issue_id": issue.ID, "counts": c,
		"self_mention_guard": "real ToolService pre-write rejection; intentionally does not reach SQLite self branch",
		"sqlite_validator":   "native duplicate mention hits WriteRunIssueComment/validateSQLiteCommentMentions; final unmentioned summary commits",
		"system_constraint":  "not weakened; synthetic adversarial model deliberately emits exec_command despite system prompt"})
	t.Log("PASS: real native Codex -> exec_command -> IPC -> FileBridge -> ToolBroker -> ToolService; self/closed/duplicate refusals are host-generated, final public summary succeeds; no extra activation")
}
